arguments.command:
cd /tmp/sv-4aa9663035c144df9f7fe8a227afc8a5 && \
# The dynamic symbol table might have better function names for the SGen worker thread
# Let's look for symbols near 0x2f4b20 and 0x2f4c84
readelf -sW libmonosgen-2.0.so.dbg | awk '{
  if ($4 == "FUNC" && $2 != "") {
    addr = strtonum("0x"$2);
    size = strtonum("0x"$3);
    if (addr <= 0x2f4b20 && addr + size > 0x2f4b20) print "0x2f4b20 -> " $NF " (at 0x" $2 ", size " $3 ")";
    if (addr <= 0x2f4c84 && addr + size > 0x2f4c84) print "0x2f4c84 -> " $NF " (at 0x" $2 ", size " $3 ")";
  }
}' | head -10

