arguments.command:
cd /tmp/sv-4aa9663035c144df9f7fe8a227afc8a5 && \
# .plt goes from 0x2ec500 to 0x2ec500+0x3310 = 0x2ef810
# .got.plt at 0x2f78e0
# So 0x2f4b20 and 0x2f4c84 are BETWEEN .plt end (0x2ef810) and .got.plt start (0x2f78e0)
# Let's see what section they're actually in
readelf -SW libmonosgen-2.0.so | awk '{
  if (NF > 5 && $1 ~ /\[/) {
    addr = strtonum("0x"$4);
    size = strtonum("0x"$6);
    if (addr <= 0x2f4b20 && addr + size > 0x2f4b20) print "0x2f4b20 is in " $2 " (0x"$4" size 0x"$6")"
    if (addr <= 0x2f4c84 && addr + size > 0x2f4c84) print "0x2f4c84 is in " $2 " (0x"$4" size 0x"$6")"
  }
}'

